style.css:
@-moz-document url-prefix("https://www.roblox.com"), url-prefix("https://www.web.roblox.com") {
/* navbar */
#header {
background-color: #9e1918;
  border-color: #9e1918;
}


  /* profile sections */
  
   .dark-theme .section-content {
    background-color: transparent !important; 
}
    .light-theme .section-content {
    background: #9e1918 !important;
}
    
    /* pfps */
    .avatar-card-image, 
    .profile-avatar-left {
        background-color: #fce1e500 !important;
}

  .slide-switcher.games {
    color: #202227;
    background:transparent !important;
}

  /* Profile groups */
  .slide-switcher .slide-item-container .slide-item-container-left {
    background-color: #9e1918 !important;
}
  .slide-switcher .slide-item-container .slide-item-container-right {
    background-color: #9e1918 !important;
}

  /* Profile collections */
.dark-theme .layer {
  background-color: #adbcdb00 !important;
}
    .light-theme .layer {
    background-color: #adbcdb00 !important;
}

  /* Profile item scroll through  */
  .profile-accoutrements-page {
    border: 1px solid #000000 !important;
}

  .page-active {
    background-color: #000000 !important;
}

  /* play button */
  .btn-common-play-game-lg {
    background-color: #4e0b0b !important;
}
    
  /* play button hover */
   .btn-common-play-game-lg:hover, .light-theme .btn-common-play-game-lg:focus {
    background-color: #691414 !important;
}

  /* Join event button */
  .btn-growth-xs {
    background-color: #4e0b0b !important;
}
  .btn-growth-xs:hover,
  .btn-growth-xs:focus {
    background-color: #691414 !important;
}

  /* Chat */
  .chat-container .chat-main .chat-header {
    background-color: #9e1918 !important;
}

  /* Avatar editor background */
  .avatar-back {
    background-image: url("https://i.imgur.com/qFmcbT0.png") !important;
}
    
    /* avatar editor navigation area */
    .rbx-tab .rbx-tab-heading {
    background-color: #9e1918 !important;
}
    .dark-theme .rbx-tabs-horizontal .rbx-tab .rbx-tab-heading:hover {
    color: #9e1918;
    background-color: #9e1918;
    box-shadow: inset 0 -4px #7f2622;
}
    .tab-horizontal-submenu {
      box-shadow: 0 1px 3px #5f1818bd !important;
}
    
    .light-theme .rbx-tabs-horizontal .rbx-tab .rbx-tab-heading:hover {
    color: #9e1918;
    background-color: #ffa3ca;
    box-shadow: inset 0 -4px #7f2622;
}

.light-theme .section-content.remove-panel {
    background-color: transparent !Important;
}
    
    /* groups */
    .groups-list-sidebar {
    background-color: #9e1918;
    border-left: 1px solid #9e1918;
}
    .group-section-content {
    background-color: #9e1918;
}
    
    .dark-theme .input-field {
        color: #ffffff !important;
}
    
    
    /* group wall */
    .group-details .group-wall .comment {
    background-color: #9e1918;
}
        
  /* Friend list */
  .avatar-card-container {
    background-color: #9e1918 !important;
}
    .dark-theme .avatar-card-btns {
    background:transparent !important;
}

  /* Left column (sidebar) */
  .rbx-left-col {
    background-color: #9e1918 !important;
}
    
    
    /* inventory */
    .light-theme .rbx-tabs-vertical .category-tabs .menu-vertical {
    background-color: #9e1918;
}

    
    /* website text tweaks */
    
    .dark-theme p, .dark-theme .text, .dark-theme .text-default, .dark-theme .text-secondary, .dark-theme .text-description, .dark-theme .text-label, .dark-theme .text-date-hint, .dark-theme .text-info, .dark-theme .text-footer {
    color: #ffffff;
}
        .light-theme p, .light-theme .text, .light-theme .text-default, .light-theme .text-secondary, .light-theme .text-description, .light-theme .text-label, .light-theme .text-date-hint, .light-theme .text-info, .light-theme .text-footer {
    color: #000;
}

.light-theme .breadcrumb-container {
    color: #000000;
}

.profile-header-username {
  color: #000000;
}
  .profile-platform-container .profile-tab {
    color: #202227;
}

.light-theme .friends-carousel-tile-experience {
    color: #000000;
}

.light-theme .game-card-info .info-label {
    color: #000000;
}

.light-theme .rbx-header .text-header {
    color: #000000 !important;
}

.light-mode, .content-default {
    color: #000000;
}

.light-mode, .content-muted {
    color: #000000;
}
.light-theme .input-group-btn .input-dropdown-btn {
    color: #000000;
    background-color: transparent;
    border-color: #000000;
    border-radius: 8px;
}

.group-details .rbx-tabs-horizontal .group-foundation-tabs .rbx-tab .rbx-tab-heading .text-lead {
    color: #000000;
}

a, a:link, a:hover, a:focus, a:visited, a:active {
    color: #000000;
} 
.light-theme .menu-vertical .menu-option .menu-option-content {
    color: #000000;
}

/* catalog */
#catalog-react-container .catalog-revamp .catalog-item-container .item-card-thumb-container {
    background-color: transparent !important;
}

.light-theme .text-robux-tile {
    color: #000000;
}

/*Background*/
body, .content
{
     background: transparent !important;
}
.light-theme, .dark-theme, .nav-content
{
     width: 100% !important;
     height: 100% !important;
     background-attachment: fixed !important;
       background-size: cover !important; /* stretch width and height */
  background-repeat: no-repeat;
  background-position: center;
    background-image: url("data:image/jpeg;base64,") !important;
}
}
